agent_detail.agent_sql:
SELECT DISTINCT ?team_fifa_api_id WHERE {
  ?ta a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/team_fifa_api_id> ?team_fifa_api_id ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/buildUpPlaySpeed> ?speed .
  FILTER(xsd:integer(?speed) > 50 && xsd:integer(?speed) < 60)
}

SELECT ?team_long_name ?buildUpPlaySpeed WHERE {
  ?ta a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/buildUpPlaySpeed> ?buildUpPlaySpeed ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/hasTeam> ?t .
  ?t <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Team/team_long_name> ?team_long_name .
}
ORDER BY DESC(xsd:integer(?buildUpPlaySpeed))
LIMIT 4

SELECT DISTINCT ?teamLongName WHERE {
  {
    SELECT (AVG(?bup) AS ?avgBup) WHERE {
      ?ta a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?date ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/buildUpPlayPassing> ?bup .
      FILTER(SUBSTR(STR(?date),1,4) = "2012")
    }
  }
  ?ta2 a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes> ;
       <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/date> ?date2 ;
       <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/buildUpPlayPassing> ?bup2 ;
       <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/TeamAttributes/hasTeam> ?team .
  FILTER(SUBSTR(STR(?date2),1,4) = "2012")
  FILTER(xsd:decimal(?bup2) > ?avgBup)
  ?team <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Team/team_long_name> ?teamLongName .
}

SELECT ?name (COUNT(?league) AS ?n) WHERE {
  ?league a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League/name> ?name .
}
GROUP BY ?name
ORDER BY DESC(?n)
LIMIT 1

SELECT (AVG(?ls) AS ?avgLongShots) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> "Ahmed Samir Farag" ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/long_shots> ?ls .
}

SELECT (COUNT(?p) AS ?total) (SUM(?leftFlag) AS ?leftCount) (100.0 * SUM(?leftFlag) / COUNT(?p) AS ?pct)
WHERE {
  {
    SELECT ?p (SAMPLE(?foot) AS ?anyfoot) WHERE {
      ?player a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player> ;
              <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_api_id> ?p ;
              <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/birthday> ?b .
      ?pa a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?p ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> ?foot .
      BIND(SUBSTR(STR(?b),1,4) AS ?year)
      FILTER(xsd:integer(?year) >= 1987 && xsd:integer(?year) <= 1992)
    }
    GROUP BY ?p
  }
  BIND(IF(?anyfoot = "left", 1, 0) AS ?leftFlag)
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/birthday> ?bday .
  FILTER(SUBSTR(STR(?bday),1,7) = "1970-10")
}

SELECT (AVG(?rating) AS ?avgRating)
WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/height> ?height .
  FILTER(xsd:decimal(?height) > 170)
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?date ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating .
  BIND(SUBSTR(STR(?date),1,4) AS ?year)
  FILTER(?year >= "2010" && ?year <= "2015")
}

SELECT (xsd:decimal(?avg1) - xsd:decimal(?avg2) AS ?diff) WHERE {
  {
    SELECT (AVG(?bc1) AS ?avg1) WHERE {
      ?p1 a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_name> "Abdou Diallo" ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id1 .
      ?pa1 a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id1 ;
           <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc1 .
    }
  }
  {
    SELECT (AVG(?bc2) AS ?avg2) WHERE {
      ?p2 a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_name> "Aaron Appindangoye" ;
          <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id2 .
      ?pa2 a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id2 ;
           <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/PlayerAttributes/ball_control> ?bc2 .
    }
  }
}

SELECT ?leagueName WHERE {
  ?league a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League/name> ?leagueName ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League/hasCountry> ?country .
  FILTER(?leagueName = "Scotland Premier League")
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/birthday> ?birthday .
  FILTER(?player_name IN ("Aaron Lennon", "Abdelaziz Barrada"))
}
ORDER BY ASC(?birthday)
LIMIT 1

SELECT (COUNT(DISTINCT ?p) AS ?n) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/birthday> ?bday ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/attacking_work_rate> ?awr .
  FILTER(SUBSTR(STR(?bday), 1, 4) < "1986")
  FILTER(LCASE(STR(?awr)) = "low")
}

SELECT (COUNT(?pa) AS ?n) WHERE {
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/preferred_foot> ?foot ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/attacking_work_rate> ?awr .
  FILTER(LCASE(STR(?foot)) = "left")
  FILTER(LCASE(STR(?awr)) = "low")
}

SELECT ?player_name WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260804-235134/ontology/vkg-bird_european_football_2/Player/height> ?height .
}
ORDER BY DESC(xsd:integer(?height))
LIMIT 1

SELECT ?player_id ?age WHERE {
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?papi ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/sprint_speed> ?ss ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?d .
  FILTER(xsd:integer(?ss) >= 97)
  BIND(SUBSTR(STR(?d),1,4) AS ?year)
  FILTER(?year >= "2013" && ?year <= "2015")

  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?papi ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/id> ?player_id ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/birthday> ?bday .

  BIND(SUBSTR(STR(?bday),1,4) AS ?byear)
  BIND((xsd:integer(SUBSTR(STR(NOW()),1,4)) - xsd:integer(?byear)) AS ?age)
}
GROUP BY ?player_id ?age

SELECT (COUNT(?l) AS ?n) WHERE {
  ?l a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League/name> "Belgium Jupiler League" .
}

SELECT (AVG(?rating) AS ?avgRating) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> "Pietro Marino" ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating .
}

SELECT ((?r1 - ?r2) / ?r2 * 100 AS ?pctHigher)
WHERE {
  {
    SELECT (AVG(?rating1) AS ?r1)
    WHERE {
      ?p1 a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> "Ariel Borysiuk" ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id1 .
      ?pa1 a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id1 ;
           <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating1 .
    }
  }
  {
    SELECT (AVG(?rating2) AS ?r2)
    WHERE {
      ?p2 a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> "Paulin Puel" ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?id2 .
      ?pa2 a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
           <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?id2 ;
           <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?rating2 .
    }
  }
}

SELECT ?name (COUNT(?l) AS ?n) WHERE {
  ?l a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/League/name> ?name .
}
GROUP BY ?name
ORDER BY DESC(?n)
LIMIT 1

SELECT ?player_name (AVG(?heading_accuracy) AS ?avgHeadingAccuracy) WHERE {
  ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/height> ?height ;
     <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
      <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/heading_accuracy> ?heading_accuracy .
  FILTER(xsd:decimal(?height) > 180)
}
GROUP BY ?player_name
ORDER BY DESC(?avgHeadingAccuracy)
LIMIT 10

SELECT ?overall_rating WHERE {
  ?player a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
    <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> "Gabriel Tamas" ;
    <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?apiId .
  ?pa a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes> ;
    <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/player_api_id> ?apiId ;
    <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/date> ?date ;
    <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/PlayerAttributes/overall_rating> ?overall_rating .
  FILTER(SUBSTR(STR(?date), 1, 4) = "2011")
}

SELECT ?player_name (AVG(?finishing) AS ?avgFinishing)
WHERE {
  {
    SELECT ?player_api_id WHERE {
      ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
         <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/height> ?h ;
         <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?player_api_id .
    }
    ORDER BY DESC(xsd:decimal(?h))
    LIMIT 1
  }
  UNION
  {
    SELECT ?player_api_id WHERE {
      ?p a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
         <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/height> ?h ;
         <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?player_api_id .
    }
    ORDER BY ASC(xsd:decimal(?h))
    LIMIT 1
  }

  ?player a <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player> ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_api_id> ?player_api_id ;
          <http://bird-bird_european_football_2-ontology-20260804-125340/ontology/vkg-bird_european_football_2/Player/player_name> ?player_name .

